#!/bin/sh
# Copy the browser client out of a crawl checkout into client/, where the
# server build embeds it.
#
# usage: scripts/sync-client.sh <path to crawl-ref/source>
#
# The checkout must have been built with `make WEBTILES=y`: the tile sheets
# and title images are generated by that build.
set -eu

src=${1:?usage: $0 <path to crawl-ref/source>}
dest=$(cd "$(dirname "$0")/../client" && pwd)
web=$src/webserver

for generated in game_data/static/main.png game_data/static/tileinfo-main.js \
                 static/stone_soup_icon-32x32.png webtiles/version.txt; do
    if [ ! -f "$web/$generated" ]; then
        echo "$0: $web/$generated is missing." >&2
        echo "Build crawl first: (cd $src && make WEBTILES=y)" >&2
        exit 1
    fi
done

for dir in static templates game_data games.d; do
    rm -rf "${dest:?}/$dir"
    cp -r "$web/$dir" "$dest/$dir"
done
cp "$web/webtiles/version.txt" "$dest/version.txt"

echo "client/ now holds the client from crawl $(cat "$dest/version.txt")"
